#!/usr/bin/env python3
import base64,gzip,hashlib,pathlib,sys
BASE_SHA="17913f7b7a9eebc027a8c59ddd605eed56d886eec0e77ac4f8ec9f3b2e1f8fe4"
FIXED_SHA="b1895254bf4b5d6c242185787bfb687f717bc3268eb5e0cd1955d47a0293b481"
PAYLOAD=""""""
root=pathlib.Path(sys.argv[1] if len(sys.argv)>1 else ".")
path=root/"src-tauri/src/shorts_factory.rs"
old=path.read_bytes()
actual=hashlib.sha256(old).hexdigest()
if actual!=BASE_SHA:
    raise SystemExit(f"unexpected shorts_factory.rs baseline {actual}")
new=gzip.decompress(base64.b64decode(PAYLOAD))
if hashlib.sha256(new).hexdigest()!=FIXED_SHA:
    raise SystemExit("shorts media fix payload checksum mismatch")
path.write_bytes(new)
print("VYRON 2.1.4 Shorts media resolver fix applied")
